def _validate_payload(data):
    """Raise an appropriate exception if *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    invalid_keys = [key for key in data if not isinstance(key, str)]
    if invalid_keys:
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    Validation can be skipped for older clients by setting ``legacy_mode`` to
    ``True``.
    """
    if not legacy_mode:
        _validate_payload(data)

    return process(data)

def _validate_request_data(data):
    """Validate the shape of an incoming request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if any(not isinstance(key, str) for key in data):
        raise TypeError("data keys must be strings")


def handle_request(data):
    """Validate an incoming API request payload before processing it."""
    _validate_request_data(data)
    return process(data)

